def _clean(intervals):
    """Yield (start, end) tuples with start < end only."""
    for pair in intervals:
        start, end = pair
        if start < end:
            yield (start, end)


def merge(intervals):
    """Merge overlapping and touching intervals; return sorted list of tuples."""
    result = []
    for start, end in sorted(_clean(intervals)):
        if result and start <= result[-1][1]:
            if end > result[-1][1]:
                result[-1] = (result[-1][0], end)
        else:
            result.append((start, end))
    return result


def free_gaps(intervals, window):
    """Maximal sub-ranges of window (ws, we) not covered by any interval."""
    ws, we = window
    if ws >= we:
        return []
    clipped = []
    for start, end in _clean(intervals):
        s = start if start > ws else ws
        e = end if end < we else we
        if s < e:
            clipped.append((s, e))
    merged = merge(clipped)
    gaps = []
    cursor = ws
    for start, end in merged:
        if start > cursor:
            gaps.append((cursor, start))
        cursor = end
        if cursor >= we:
            break
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals):
    """Largest number of non-empty intervals covering one common point."""
    events = []
    for start, end in _clean(intervals):
        events.append((start, 1))
        events.append((end, -1))
    # At equal points, closes (-1) come before opens (1): half-open semantics.
    events.sort(key=lambda ev: (ev[0], ev[1]))
    depth = 0
    best = 0
    for _, delta in events:
        depth += delta
        if depth > best:
            best = depth
    return best

