"""Half-open integer interval utilities."""


def _clean(intervals):
    """Yield (start, end) tuples, ignoring empty or inverted pairs."""
    for pair in intervals:
        start, end = pair
        if start < end:
            yield start, end


def merge(intervals):
    """Merge overlapping and touching half-open intervals; ignore empty ones.

    Returns a list of (start, end) tuples sorted by start. O(n log n).
    """
    cleaned = sorted(_clean(intervals))
    if not cleaned:
        return []
    result = [list(cleaned[0])]
    for start, end in cleaned[1:]:
        current = result[-1]
        if start <= current[1]:
            if end > current[1]:
                current[1] = end
        else:
            result.append([start, end])
    return [(s, e) for s, e in result]


def free_gaps(intervals, window):
    """Maximal sub-ranges of [ws, we) not covered by any interval, in order."""
    ws, we = window
    if ws >= we:
        return []
    clipped = [(max(s, ws), min(e, we)) for s, e in _clean(intervals)]
    merged = merge(clipped)
    gaps = []
    cursor = ws
    for start, end in merged:
        if start > cursor:
            gaps.append((cursor, start))
        cursor = max(cursor, end)
        if cursor >= we:
            break
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals):
    """Largest number of non-empty intervals covering one common point.

    Half-open semantics: (1, 3) and (3, 5) do not overlap. O(n log n).
    """
    events = []
    for start, end in _clean(intervals):
        events.append((start, 1))
        events.append((end, -1))
    if not events:
        return 0
    # At equal coordinates, process ends before starts: a point x is
    # covered by [s, e) iff s <= x < e.
    events.sort(key=lambda ev: (ev[0], ev[1]))
    current = best = 0
    for _, delta in events:
        current += delta
        if current > best:
            best = current
    return best

